// Named combos that get their own page at /drinks/<slug>. Pages are generated by scripts/build-pages.js.
// Every combo uses only bases, flavors and extras from lib/menu.js, so the order line is always one the app can say.
// Descriptions are ours. Avoid 7 Brew's own drink names (Blondie, Brunette, Cinnamon Roll, ...) and candy brand names.

const d = (slug, name, drink, temp, flavors, { size = 'medium', milk = '', extras = [], sweet = 'regular' } = {}, blurb) =>
  ({ slug, name, combo: { drink, temp, size, milk, flavors, extras, sweet, sf: false }, blurb });

